System.out.println("=== SELECT * (wszystkie kolumny) ===");
print(stmt.executeQuery("SELECT * FROM products"));
// Gwiazdka (*) oznacza 'wszystkie kolumny tabeli' - wygodne do szybkiego
// podgladu, ale w kodzie produkcyjnym lepiej wymieniac kolumny jawnie:
// SELECT * jest wrazliwy na zmiany struktury tabeli (dodanie kolumny
// moze niespodziewanie zmienic wynik zapytania w aplikacji).

System.out.println("\n=== Konkretne kolumny (name, price) ===");
print(stmt.executeQuery("SELECT name, price FROM products"));
// Wymieniamy tylko te kolumny, ktore nas interesuja - czytelniej
// i wydajniej (baza nie musi przesylac zbednych danych).

System.out.println("=== Aliasy (AS) ===");
print(stmt.executeQuery("""
    SELECT name AS nazwa_produktu, price AS cena_pln
    FROM products
    """));

System.out.println("\n=== Alias na wyrazeniu obliczanym ===");
print(stmt.executeQuery("""
    SELECT name, price, price * 1.23 AS cena_z_vat
    FROM products
    """));
// AS pozwala nadac kolumnie (lub wyrazeniu) inna nazwe w wyniku -
// przydatne przy wyrazeniach obliczanych albo zeby wynik byl
// czytelniejszy. Slowo AS jest OPCJONALNE (mozna je pominac).

System.out.println("=== DISTINCT (unikalne kategorie) ===");
print(stmt.executeQuery("SELECT DISTINCT category FROM products"));
// Nawet jesli mamy 6 produktow w 2 kategoriach, wynik da TYLKO 2 wiersze.

System.out.println("\n=== WHERE (price > 100) ===");
print(stmt.executeQuery("SELECT name, price FROM products WHERE price > 100"));
// WHERE filtruje wiersze na podstawie warunku logicznego.
// Glebsze operatory (AND, OR, LIKE, BETWEEN, IN, IS NULL...) -> Lesson11_Filtering.

System.out.println("=== LIMIT 3 ===");
print(stmt.executeQuery("SELECT id, name FROM products ORDER BY id LIMIT 3"));
// LIMIT n zwraca co najwyzej n pierwszych wierszy. Bez ORDER BY kolejnosc
// NIE jest gwarantowana przez standard SQL - zawsze lacz LIMIT z ORDER BY!

System.out.println("\n=== LIMIT 3 OFFSET 3 (strona 2, po 3 wiersze) ===");
print(stmt.executeQuery("SELECT id, name FROM products ORDER BY id LIMIT 3 OFFSET 3"));
// OFFSET n pomija pierwsze n wierszy. LIMIT + OFFSET razem to klasyczny
// mechanizm PAGINACJI - np. strona 2 po 3 produkty: LIMIT 3 OFFSET 3.
